-- MARK c13-v9 - IND
-- Waspadalah dan kamu dirimu–sendiri mereka–akan–menyerahkan kamu ke sanhedrin dan ke sinagoga-sinagoga kamu–akan–dipukuli dan di–hadapan penguasa-penguasa dan raja-raja kamu–akan–berdiri karena Aku untuk kesaksian kepada–mereka
BEGIN;
-- 4101300901: Βλέπετε (G0991) → "Waspadalah" [opus-4.5-chirho]
WITH np AS (
  INSERT INTO phrase (language_id, created_at)
  SELECT (SELECT id FROM language WHERE code = 'ind'), NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
    WHERE pw.word_id = '4101300901' AND p.language_id = (SELECT id FROM language WHERE code = 'ind') AND p.deleted_at IS NULL
  )
  RETURNING id
)
